mapper.insert:
INSERT INTO po_detail ( POD_ID, PO_ID, COMPANY_CODE, PRODUCT_CODE, ORDER_QTY, UNIT_PRICE, DC_AMT, SUP_AMT, VAT_AMT, PRODUCT_NAME, VAT_TYPE ) SELECT POD_ID_SEQ.NEXTVAL, #{poId}, #{companyCode}, t.productCode, t.orderQty, t.unitPrice, t.dcAmt, t.supAmt, t.vatAmt, t.productName, t.vatType FROM (
SELECT #{d.productCode} AS productCode, #{d.orderQty} AS orderQty, #{d.unitPrice} AS unitPrice, #{d.dcAmt} AS dcAmt, #{d.supAmt} AS supAmt, #{d.vatAmt} AS vatAmt, #{d.productName} AS productName, #{d.vatType} AS vatType FROM DUAL
) t

mapper.update:
UPDATE PURCHASE_ORDER
SET PO_STATUS = #{poStatus}
WHERE PO_CODE = #{poCode}

mapper.insert:
INSERT INTO DO_DETAIL ( DOD_NO, DO_NO, PRODUCT_CODE, QTY, UNIT_PRICE, SUP_AMT, VAT_AMT, DC_AMT, COMPANY_CODE ) SELECT fn_generate_code('DOD', ''), #{doNo}, t.productCode, t.qty, t.unitPrice, t.supAmt, t.vatAmt, t.dcAmt, #{companyCode} FROM (
SELECT #{d.productCode} AS productCode, #{d.qty} AS qty, #{d.unitPrice} AS unitPrice, #{d.supAmt} AS supAmt, #{d.vatAmt} AS vatAmt, #{d.dcAmt} AS dcAmt FROM DUAL
) t

