INSERT INTO CREDIT_MASTER(
  CUS_CODE, CREDIT_LIMIT, CREDIT_GRADE,
  START_DATE, EXPIRE_DATE, DUE_DATE,
  ACTIVE_STATUS, COMPANY_CODE, MANAGER
)
VALUES (
  #{cusCode}, #{creditLimit}, #{creditGrade},
  #{startDate}, #{endDate}, #{dueDate},
  #{activeStatus}, #{companyCode}, #{manager}
)

mapper.update:
UPDATE CUSTOMER
CEO_NAME = #{ceoName}, EMP_NAME = #{empName}, CEMP_NAME = #{cempName}, CUS_NAME = #{cusName}, BIZ_NO = #{bizNo}, BIZ_TYPE = #{bizType}, BIZ_CATEGORY = #{bizCategory}, TEL = #{tel}, EMAIL = #{email}, ADDR = #{addr}, ZIP_CODE = #{zipCode}, ACTIVE_STATUS = #{activeStatus}, GBN = #{gbn}, BANK_NAME = #{bankName}, BANK_ACCOUNT = #{bankAccount},
WHERE CUS_CODE = #{cusCode}

mapper.select:
SELECT company_code, cus_code, cus_name, credit_grade, credit_limit, start_date, expire_date, remain_limit, manager_name, status FROM V_CREDIT_EXPOSURE WHERE company_code = #{companyCode}
AND credit_grade = #{grade}
AND (UPPER(cus_name) LIKE '%'||UPPER(#{name})||'%' OR TO_CHAR(cus_code) LIKE '%'||#{name}||'%')
AND (UPPER(manager_name) LIKE '%'||UPPER(#{manager})||'%')
ORDER BY cus_name

SELECT company_code, cus_code, credit_grade, credit_limit, due_date,
       start_date, expire_date, left_price, NVL(active_status,'Y') AS active_status,
       emp_name
FROM   credit_master
WHERE  company_code = #{companyCode}
  AND  cus_code     = #{cusCode}

mapper.update:
UPDATE credit_master
   SET active_status = 'N',
       expire_date   = NVL(expire_date, SYSDATE)
 WHERE company_code = #{companyCode}
   AND cus_code     = #{cusCode}

